package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.widget.TextView;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.junit.Test;import java.io.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Delayed real asset decode must not replace a user's already visible Save/Use control. No output. */
public final class ToneWaveArrivalTest {
 final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);AlarmEditorActivity activity;
 View find(View root,String text){if(root instanceof TextView&&text.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View found=find(group.getChildAt(n),text);if(found!=null)return found;}return null;}
 void await(java.util.function.BooleanSupplier yes)throws Exception{long end=SystemClock.elapsedRealtime()+8000;while(!yes.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(20);assertTrue(yes.getAsBoolean());}
 @Test public void realWaveArrivalPreservesExactUseButtonAndItsSingleDeliveredAction()throws Exception{
  assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());assertEquals(0,Prefs.number(c,"checkPending",0));CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AlarmToneScreen.WaveSource old=AlarmToneScreen.waveSource;AlarmToneAudio.Provider oldAudio=AlarmToneAudio.provider;java.util.concurrent.atomic.AtomicInteger opens=new java.util.concurrent.atomic.AtomicInteger();
  try(AlarmSkipFixture f=new AlarmSkipFixture()){
   try{i.runOnMainSync(()->{AlarmToneScreen.waveSource=app->{entered.countDown();try{if(!release.await(30,TimeUnit.SECONDS))throw new IOException("Asset fixture release timeout");}catch(InterruptedException e){throw new IOException(e);}return old.load(app);};AlarmToneAudio.provider=app->new AlarmTonePreview.Port(){public AlarmTonePreview.Session open(String tone,float gain,AlarmTonePreview.Events events){opens.incrementAndGet();throw new AssertionError("No preview output in asset arrival test");}public void close(){}};});Alarm initial=f.load();initial.enabled=false;Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",initial.json().toString()).putExtra("route","sound").putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(entered.await(5,TimeUnit.SECONDS));await(()->activity.hasWindowFocus());View[] before={null};i.runOnMainSync(()->{assertFalse(activity.toneAssetsReady());before[0]=find(activity.getWindow().getDecorView(),"Use Daybreak");assertNotNull(before[0]);assertTrue(before[0].isClickable());});release.countDown();await(()->{boolean[] loaded={false};i.runOnMainSync(()->loaded[0]=activity.toneAssetsReady());return loaded[0];});CountDownLatch frame=new CountDownLatch(1);Rect bounds=new Rect();i.runOnMainSync(()->{assertSame("Auxiliary wave arrival preserves action identity",before[0],find(activity.getWindow().getDecorView(),"Use Daybreak"));View root=activity.getWindow().getDecorView();root.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);root.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));i.runOnMainSync(()->{View button=find(activity.getWindow().getDecorView(),"Use Daybreak");assertSame(before[0],button);assertTrue(button.isAttachedToWindow()&&button.isEnabled()&&button.hasWindowFocus());Rect visible=new Rect();assertTrue(button.getGlobalVisibleRect(visible));assertEquals(button.getHeight(),visible.height());assertEquals(button.getWidth(),visible.width());assertTrue(visible.height()>=Design.dp(c,48)&&visible.width()>=Design.dp(c,48));int[] location=new int[2];button.getLocationOnScreen(location);bounds.set(location[0],location[1],location[0]+button.getWidth(),location[1]+button.getHeight());});assertTrue(d.click(bounds.centerX(),bounds.centerY()));await(()->{boolean[] edit={false};i.runOnMainSync(()->edit[0]=find(activity.getWindow().getDecorView(),"Edit alarm")!=null);return edit[0];});assertEquals(0,opens.get());assertEquals(0,f.schedules);
   }finally{try{release.countDown();if(activity!=null){i.runOnMainSync(activity::finish);await(activity::isDestroyed);assertTrue(activity.awaitToneClosed(8000));}}finally{i.runOnMainSync(()->{AlarmToneScreen.waveSource=old;AlarmToneAudio.provider=oldAudio;});}}
  }
 }
}
